WITH unpacked AS (SELECT id, plan, effective_from, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT plan, CASE WHEN avg_tier_price >= 26 THEN 'PREMIUM' ELSE 'STANDARD' END AS avg_tier_price_tier, COUNT(*) AS event_count, COUNT(*) AS event_count_2, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count, PERCENTILE_APPROX(entry_price, 0.9) AS entry_price_p90, AVG(entry_price) FILTER (WHERE plan = 'starter') AS starter_avg_entry_price, COUNT(*) FILTER (WHERE plan = 'pro') AS pro_rows, DENSE_RANK() OVER (PARTITION BY plan ORDER BY COUNT(*) DESC) AS event_count_2_dense_rank FROM unpacked GROUP BY 1, 2;
